challenge.verificationSource:
mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("enqueue3 enqueue5 enqueue8 dequeue dequeue enqueue2 front","8"),
        ("enqueue1 enqueue2 dequeue front","2"),
        ("enqueue9 front","9"),
        ("enqueue1 enqueue2 dequeue enqueue3 front","2"),
        ("enqueue4 enqueue5 enqueue6 dequeue front","5"),
        ("  \nenqueue3 enqueue5 enqueue8 dequeue dequeue enqueue2 front\n  ","8"),
        ("\nenqueue4 enqueue5 enqueue6 dequeue front\n","5")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS queue-with-stacks");
}
